250	                appendToCorpus(results);
251	                results.length = 0;
252	                progress.quests.lastIndex = i + 1;
253	                saveProgress(progress);
254	            }
255	        }
256	        appendToCorpus(results);
257	        progress.quests.lastIndex = questsData.length;
258	        saveProgress(progress);
259	    } catch (err) {
260	        logger.error({ err }, 'Quest corpus generation failed');
261	    }
262	
263	    // ── 4. Mechanics Corpus Generation ─────────────────────────────────
264	    try {
265	        logger.info('Processing Mechanics Pages...');
266	        const results = [];
267	        for (const page of MECHANICS_PAGES) {
