281	    } catch (err) {
282	        logger.error({ err }, 'Mechanics corpus generation failed');
283	    }
284	}
285	
286	generate().catch(err => {
287	    logger.error({ err }, 'Corpus generation failed');
288	    process.exit(1);
289	});
