1	/**
2	 * WikiEquipmentEnricher.ts
3	 *
4	 * Structured parser for RS Wiki Infobox templates and drop tables.
5	 * Extracts equipment bonuses, item metadata, monster stats, and complete
6	 * drop tables (including sub-table resolution) with respectful rate limiting.
7	 *
8	 * Sovereign Substrate: Semantic Enrichment Layer
9	 * Cache Authority: D:\sovereign\atlas\wiki\cache\
10	 *
11	 * Template Coverage:
12	 *   - {{Infobox Bonuses}}  → Equipment combat stats
13	 *   - {{Infobox Item}}     → Item metadata
14	 *   - {{Infobox Monster}}  → Monster/NPC stats
15	 *   - {{DropsLine}}        → Individual drop entries
16	 *   - {{Rare drop table}}, {{Gem drop table}}, etc. → Sub-table resolution
17	 */
18	
19	import { createLogger } from './logger.js';
20	import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'fs';
21	import { join } from 'path';
22	import { QueryClassifier, QueryType } from './QueryClassifier.js';
23	import { CacheForensicsLimb } from '../limbs/spatial/CacheForensicsLimb.js';
24	import { GeApi, GePrice } from './GeApi.js';
25	import { BestiaryApi, BestiaryBeastData } from './BestiaryApi.js';
26	
27	const logger = createLogger('WikiEquipmentEnricher');
28	
29	// ═══════════════════════════════════════════════════════
30	// Interfaces
31	// ═══════════════════════════════════════════════════════
32	
33	export interface WikiEquipmentBonuses {
34	    tier: number;
35	    slot: string;          // mainhand, off-hand, 2h, head, body, legs, feet, hands, back, neck, ring, ammo, pocket, shield
36	    class: string;         // melee, ranged, magic, necromancy, all, hybrid
37	    style: string;         // slash, stab, crush, none
38	    damage: number;
39	    accuracy: number;
40	    armour: number;
41	    lifeBonus: number;
42	    prayerBonus: number;
43	    attackSpeed: string;   // fastest, fast, average, slow, slowest
44	}
45	
46	export interface WikiItemMeta {
47	    name: string;
48	    examine: string;
49	    tradeable: boolean;
50	    stackable: boolean;
51	    members: boolean;
52	    weight: number;
53	    highAlch: number;
54	    lowAlch: number;
55	    /** Grand Exchange price in coins. 0 = not on GE or unknown. */
56	    geValue: number;
57	    _geSource?: string;
58	    _geTimestamp?: number;
59	    quest: string;
60	    release: string;
61	}
62	
63	export interface WikiMonsterMeta {
64	    name: string;
65	    combatLevel: number;
66	    lifePoints: number;
67	    maxHit: number;
68	    weakness: string;
69	    slayerLevel: number;
70	    slayerCategory: string;
71	    aggressive: boolean;
72	    poisonous: boolean;
73	    attackStyle: string;
74	    members: boolean;
75	    experience: number;
76	    
77	    // March 2026 Combat Affinities
78	    defence: number;
79	    armour: number;
80	    affinityMelee: number;
81	    affinityRanged: number;
82	    affinityMagic: number;
83	    affinityNecromancy: number;
84	}
85	
86	export interface WikiDropEntry {
87	    itemName: string;
88	    quantity: string;       // "1", "1-3", "1 (noted)", etc.
89	    rarity: string;         // "Always", "Common", "Uncommon", "Rare", "Very rare", "1/128"
90	    isMembers: boolean;
91	    notes: string;
92	    /** Grand Exchange value in coins. 0 = not tradeable or unknown. Used by LootBeamRegistry. */
93	    geValue: number;
94	}
95	
96	export interface WikiDropTable {
97	    section: string;        // "Main", "Charms", "Tertiary", sub-table name
98	    entries: WikiDropEntry[];
99	}
100	
101	export interface WikiPageData {
102	    title: string;
103	    fetchedAt: number;
104	    bonuses: WikiEquipmentBonuses | null;
105	    itemMeta: WikiItemMeta | null;
106	    monsterMeta: WikiMonsterMeta | null;
107	    dropTables: WikiDropTable[];
108	    rawVariables: Record<string, string>;
109	    pageType?: 'npc' | 'item' | 'equipment' | 'place' | 'mechanic' | 'lore';
110	    extract?: string;
111	    categoryMembers?: string[];
112	}
113	
114	export interface WikiUpdateMeta {
115	    title: string;
116	    date: string;
117	    category: string;
118	    url: string;
119	    isHotfix: boolean;
120	    isColdfix: boolean;
121	    affectedEntities: number[];
122	}
123	
124	// ═══════════════════════════════════════════════════════
125	// Generic Enrichment Types
126	// ═══════════════════════════════════════════════════════
127	
128	export interface WikiGenericMeta {
129	    title: string;
130	    pageType: 'npc' | 'item' | 'equipment' | 'place' | 'mechanic' | 'lore';
131	    extract: string;
132	    infoboxVars: Record<string, string>;
133	    categoryMembers?: string[];
134	    fetchedAt: number;
135	}
136	
137	export class WikiEquipmentEnricher {
138	    private static instance: WikiEquipmentEnricher;
139	
140	    private readonly API_BASE = 'https://runescape.wiki/api.php';
141	    private readonly USER_AGENT = 'POG2-Sovereign/1.0 (Sovereign Research Node; admin@pog2.internal; respectful-soft-parse; +https://github.com/Kbro1989/POG2)';
142	    private readonly RATE_LIMIT_MS = 1500;
143	    private readonly CACHE_DIR: string;
144	    private readonly CACHE_TTL_MS = 7 * 24 * 60 * 60 * 1000; // 7 days
145	
146	    private lastRequestTime = 0;
147	    private requestCount = 0;
148	
149	    private constructor() {
150	        this.CACHE_DIR = join('D:', 'sovereign', 'atlas', 'wiki', 'cache');
151	        this.ensureCacheDir();
152	    }
153	
154	    public static getInstance(): WikiEquipmentEnricher {
155	        if (!this.instance) {
156	            this.instance = new WikiEquipmentEnricher();
157	        }
158	        return this.instance;
159	    }
160	
161	    // ── Cache Layer ────────────────────────────────────────
162	
163	    private ensureCacheDir(): void {
164	        const dirs = [
165	            this.CACHE_DIR,
166	            join(this.CACHE_DIR, 'items'),
167	            join(this.CACHE_DIR, 'monsters'),
168	            join(this.CACHE_DIR, 'templates'),
169	            join(this.CACHE_DIR, 'wikitext'),
170	            join(this.CACHE_DIR, 'generic')
171	        ];
172	        for (const dir of dirs) {
173	            if (!existsSync(dir)) {
174	                mkdirSync(dir, { recursive: true });
175	            }
176	        }
177	    }
178	
179	    private sanitizeFilename(name: string): string {
180	        return name.replace(/[<>:"/\\|?*]/g, '_').replace(/\s+/g, '_').toLowerCase();
181	    }
182	
183	    private readCache(subdir: string, key: string): any | null {
184	        const filePath = join(this.CACHE_DIR, subdir, `${this.sanitizeFilename(key)}.json`);
185	        if (!existsSync(filePath)) return null;
186	
187	        try {
188	            const raw = readFileSync(filePath, 'utf8');
189	            const cached = JSON.parse(raw);
190	
191	            // TTL check
192	            if (cached._cachedAt && (Date.now() - cached._cachedAt) > this.CACHE_TTL_MS) {
193	                logger.debug({ key }, 'Cache expired, will re-fetch.');
194	                return null;
195	            }
196	
197	            return cached;
198	        } catch {
199	            return null;
200	        }
201	    }
202	
203	    private writeCache(subdir: string, key: string, data: any): void {
204	        const filePath = join(this.CACHE_DIR, subdir, `${this.sanitizeFilename(key)}.json`);
205	        try {
206	            writeFileSync(filePath, JSON.stringify({ ...data, _cachedAt: Date.now() }, null, 2), 'utf8');
207	        } catch (err) {
208	            logger.warn({ key, err }, 'Failed to write cache.');
209	        }
210	    }
211	
212	    // ── Rate Limiter ───────────────────────────────────────
213	
214	    private async throttle(): Promise<void> {
215	        const now = Date.now();
216	        const elapsed = now - this.lastRequestTime;
217	        if (elapsed < this.RATE_LIMIT_MS) {
218	            const delay = this.RATE_LIMIT_MS - elapsed;
219	            await new Promise(resolve => setTimeout(resolve, delay));
220	        }
221	        this.lastRequestTime = Date.now();
222	        this.requestCount++;
223	    }
224	
225	    // ── API Layer ──────────────────────────────────────────
226	
227	    /**
228	     * Fetch raw wikitext for a page. Checks disk cache first.
229	     */
230	    private async fetchWikitext(pageTitle: string): Promise<string | null> {
231	        const cached = this.readCache('wikitext', pageTitle);
232	        if (cached?.wikitext) {
233	            logger.debug({ title: pageTitle }, 'Wikitext served from cache.');
234	            return cached.wikitext;
235	        }
236	
237	        await this.throttle();
238	
239	        const params = new URLSearchParams({
240	            action: 'parse',
241	            format: 'json',
242	            page: pageTitle,
243	            prop: 'wikitext',
244	            origin: '*'
245	        });
246	
247	        try {
248	            const response = await fetch(`${this.API_BASE}?${params.toString()}`, {
249	                headers: {
250	                    'User-Agent': this.USER_AGENT,
251	                    'Accept': 'application/json'
252	                },
253	                signal: AbortSignal.timeout(10000)
254	            });
255	
256	            if (!response.ok) {
257	                if (response.status === 429) {
258	                    const retryAfter = response.headers.get('Retry-After');
259	                    if (retryAfter) {
260	                        ApiThrottle.getInstance().reportRetryAfter('wiki', parseInt(retryAfter, 10));
261	                    }
262	                }
263	                logger.warn({ title: pageTitle, status: response.status }, 'Wiki API non-OK response.');
264	                return null;
265	            }
266	
267	            const data = await response.json() as any;
268	            const wikitext = data.parse?.wikitext?.['*'] || null;
269	
270	            if (wikitext) {
271	                this.writeCache('wikitext', pageTitle, { wikitext });
272	                logger.info({ title: pageTitle, length: wikitext.length, request: this.requestCount }, 'Wikitext fetched.');
273	            }
274	
275	            return wikitext;
276	        } catch (err) {
277	            logger.error({ title: pageTitle, err }, 'Failed to fetch wikitext.');
278	            return null;
279	        }
280	    }
281	
282	    /**
283	     * Search for the canonical page title matching a query.
284	     */
285	    private async searchPage(query: string): Promise<string | null> {
286	        await this.throttle();
287	
288	        const params = new URLSearchParams({
289	            action: 'query',
290	            format: 'json',
291	            list: 'search',
292	            srsearch: query,
293	            srlimit: '1',
294	            origin: '*'
295	        });
296	
297	        try {
298	            const response = await fetch(`${this.API_BASE}?${params.toString()}`, {
299	                headers: { 'User-Agent': this.USER_AGENT },
300	                signal: AbortSignal.timeout(10000)
301	            });
302	
303	            if (!response.ok) {
304	                if (response.status === 429) {
305	                    const retryAfter = response.headers.get('Retry-After');
306	                    if (retryAfter) {
307	                        ApiThrottle.getInstance().reportRetryAfter('wiki', parseInt(retryAfter, 10));
308	                    }
309	                }
310	                logger.warn({ query, status: response.status }, 'Wiki search non-OK response.');
311	                return null;
312	            }
313	
314	            const data = await response.json() as any;
315	            return data.query?.search?.[0]?.title || null;
316	        } catch (err) {
317	            logger.error({ query, err }, 'Wiki search failed.');
318	            return null;
319	        }
