322	    /**
323	     * Resolves a name to wikitext. Tries direct fetch, follows redirects, falls back to search.
324	     */
325	    private async getWikitextForName(name: string): Promise<string | null> {
326	        const visited = new Set<string>();
327	        let currentName = name;
328	
329	        while (true) {
330	            if (visited.has(currentName.toLowerCase())) {
331	                logger.warn({ name, visited: [...visited] }, 'Redirect loop detected');
332	                return null;
333	            }
334	            visited.add(currentName.toLowerCase());
335	
336	            let wikitext = await this.fetchWikitext(currentName);
337	
338	            if (wikitext && wikitext.trim().startsWith('#REDIRECT')) {
339	                const redirectMatch = wikitext.match(/\[\[([^\]]+)\]\]/);
340	                if (redirectMatch) {
341	                    const redirectTarget = redirectMatch[1].trim();
342	                    logger.info({ from: currentName, to: redirectTarget }, 'Following wiki redirect...');
343	                    currentName = redirectTarget;
344	                    continue;
345	                }
346	            }
347	
348	            return wikitext;
349	        }
350	    }
