354	    /**
355	     * Extract a single template's parameters from wikitext.
356	     * Handles nested templates via bracket-depth tracking.
357	     */
358	    private extractTemplate(wikitext: string, templateName: string): Record<string, string> | null {
359	        const lowerText = wikitext.toLowerCase();
360	        const lowerName = templateName.toLowerCase();
361	
362	        let searchIdx = 0;
363	        let startIdx = -1;
364	
365	        while (searchIdx < lowerText.length) {
366	            const bracePos = lowerText.indexOf('{{', searchIdx);
367	            if (bracePos === -1) break;
368	
369	            let nameStart = bracePos + 2;
370	            while (nameStart < lowerText.length && (lowerText[nameStart] === ' ' || lowerText[nameStart] === '\n')) nameStart++;
371	
372	            if (lowerText.substring(nameStart, nameStart + lowerName.length) === lowerName) {
373	                const afterName = lowerText[nameStart + lowerName.length];
374	                if (afterName === '|' || afterName === '}' || afterName === ' ' || afterName === '\n' || afterName === '\r' || afterName === undefined) {
375	                    startIdx = bracePos;
376	                    break;
377	                }
378	            }
379	            searchIdx = bracePos + 2;
380	        }
381	
382	        if (startIdx === -1) return null;
383	
384	        // Find matching closing }} using bracket depth
385	        let depth = 0;
386	        let endIdx = startIdx;
387	        for (let i = startIdx; i < wikitext.length - 1; i++) {
388	            if (wikitext[i] === '{' && wikitext[i + 1] === '{') {
389	                depth++;
390	                i++;
391	            } else if (wikitext[i] === '}' && wikitext[i + 1] === '}') {
392	                depth--;
393	                i++;
394	                if (depth === 0) {
395	                    endIdx = i + 1;
396	                    break;
397	                }
398	            }
399	        }
400	
401	        if (depth !== 0) return null;
402	
403	        const fullContent = wikitext.substring(startIdx + 2, endIdx - 2);
404	        const pipeIdx = fullContent.indexOf('|');
405	        if (pipeIdx === -1) return {};
406	
407	        return this.parseTemplateParams(fullContent.substring(pipeIdx + 1));
408	    }
409	
410	    /**
411	     * Extract ALL instances of a template from wikitext.
412	     * Critical for DropsLine parsing where each drop is a separate template call.
413	     */
414	    private extractAllTemplateInstances(wikitext: string, templateName: string): Record<string, string>[] {
415	        const results: Record<string, string>[] = [];
416	        const lowerText = wikitext.toLowerCase();
417	        const lowerName = templateName.toLowerCase();
418	        let searchIdx = 0;
419	
420	        while (searchIdx < lowerText.length) {
421	            const bracePos = lowerText.indexOf('{{', searchIdx);
422	            if (bracePos === -1) break;
423	
424	            let nameStart = bracePos + 2;
425	            while (nameStart < lowerText.length && (lowerText[nameStart] === ' ' || lowerText[nameStart] === '\n')) nameStart++;
426	
427	            if (lowerText.substring(nameStart, nameStart + lowerName.length) === lowerName) {
428	                const afterName = lowerText[nameStart + lowerName.length];
429	                if (afterName === '|' || afterName === '}' || afterName === ' ' || afterName === '\n') {
430	                    // Find closing braces
431	                    let depth = 0;
432	                    let endIdx = bracePos;
433	                    for (let i = bracePos; i < wikitext.length - 1; i++) {
434	                        if (wikitext[i] === '{' && wikitext[i + 1] === '{') { depth++; i++; }
435	                        else if (wikitext[i] === '}' && wikitext[i + 1] === '}') {
436	                            depth--; i++;
437	                            if (depth === 0) { endIdx = i + 1; break; }
438	                        }
439	                    }
440	
441	                    const fullContent = wikitext.substring(bracePos + 2, endIdx - 2);
442	                    const pipeIdx = fullContent.indexOf('|');
443	                    if (pipeIdx !== -1) {
444	                        results.push(this.parseTemplateParams(fullContent.substring(pipeIdx + 1)));
445	                    }
446	
447	                    searchIdx = endIdx;
448	                    continue;
449	                }
450	            }
451	            searchIdx = bracePos + 2;
452	        }
453	
454	        return results;
455	    }
