457	    /**
458	     * Parse pipe-separated template parameters, respecting nested template depth.
459	     * Handles {{nested|templates}} and [[wiki|links]] inside parameter values.
460	     */
461	    private parseTemplateParams(text: string): Record<string, string> {
462	        const params: Record<string, string> = {};
463	        let depth = 0;
464	        let currentParam = '';
465	        let positionalIdx = 1;
466	
467	        for (let i = 0; i < text.length; i++) {
468	            const ch = text[i];
469	            const next = text[i + 1];
470	
471	            if (ch === '{' && next === '{') { depth++; currentParam += '{{'; i++; }
472	            else if (ch === '}' && next === '}') { depth--; currentParam += '}}'; i++; }
473	            else if (ch === '[' && next === '[') { depth++; currentParam += '[['; i++; }
474	            else if (ch === ']' && next === ']') { depth--; currentParam += ']]'; i++; }
475	            else if (ch === '|' && depth === 0) {
476	                this.assignParam(params, currentParam, positionalIdx);
477	                positionalIdx++;
478	                currentParam = '';
479	            } else {
480	                currentParam += ch;
481	            }
482	        }
483	
484	        // Last parameter
485	        if (currentParam.trim()) {
486	            this.assignParam(params, currentParam, positionalIdx);
487	        }
488	
489	        return params;
490	    }
491	
492	    private assignParam(params: Record<string, string>, raw: string, positionalIdx: number): void {
493	        const eqIdx = raw.indexOf('=');
494	        if (eqIdx > 0 && !raw.substring(0, eqIdx).includes('{{')) {
495	            const key = raw.substring(0, eqIdx).trim().toLowerCase();
496	            const value = this.cleanWikiMarkup(raw.substring(eqIdx + 1).trim());
497	            if (key) params[key] = value;
498	        } else {
499	            params[`_${positionalIdx}`] = this.cleanWikiMarkup(raw.trim());
500	        }
501	    }
502	
503	    /**
504	     * Strip wiki markup from a value (links, formatting, refs).
505	     */
506	    private cleanWikiMarkup(text: string): string {
507	        return text
508	            .replace(/\[\[(?:[^\]|]*\|)?([^\]]*)\]\]/g, '$1')  // [[Link|Text]] -> Text
509	            .replace(/'''?/g, '')                                // Bold/italic
510	            .replace(/<ref[^>]*>.*?<\/ref>/gs, '')               // References
511	            .replace(/<ref[^/]*\/>/g, '')                        // Self-closing refs
512	            .replace(/<br\s*\/?>/gi, ' ')                        // Line breaks
513	            .replace(/<!--.*?-->/gs, '')                         // HTML comments
514	            .replace(/&nbsp;/g, ' ')                             // Non-breaking spaces
515	            .trim();
516	    }
