885	    public async enrichMonster(name: string): Promise<WikiPageData> {
886	        const cached = this.readCache('monsters', name);
887	        if (cached && cached.title) {
888	            logger.debug({ name }, 'Monster enrichment served from cache.');
889	            return cached;
890	        }
891	
892	        const monsterMeta = await this.parseMonsterMeta(name);
893	        const dropTables = await this.parseDropTables(name);
894	
895	        // 🧬 Integration: Canonical Bestiary Enrichment
896	        if (monsterMeta) {
897	            const beastId = await BestiaryApi.resolveId(name);
898	            if (beastId) {
899	                const beastData = await BestiaryApi.getBeastData(beastId);
900	                if (beastData) {
901	                    monsterMeta.combatLevel = beastData.level;
902	                    monsterMeta.lifePoints = beastData.lifepoints;
903	                    monsterMeta.weakness = beastData.weakness;
904	                    monsterMeta.slayerLevel = beastData.slayerlevel;
905	                    monsterMeta.slayerCategory = beastData.slayercat;
906	                    monsterMeta.aggressive = beastData.aggressive;
907	                    monsterMeta.poisonous = beastData.poisonous;
908	                    monsterMeta.members = beastData.members;
909	                    logger.debug({ name, id: beastId }, 'Canonical Bestiary data applied to monster meta.');
910	                }
911	            }
912	        }
913	
914	        const wikitext = await this.getWikitextForName(name);
915	        const rawVariables = wikitext
916	            ? (this.extractTemplate(wikitext, 'Infobox Monster') || {})
917	            : {};
918	
919	        const result: WikiPageData = {
920	            title: name,
921	            fetchedAt: Date.now(),
922	            bonuses: null,
923	            itemMeta: null,
924	            monsterMeta,
925	            dropTables,
926	            rawVariables
927	        };
928	
929	        this.writeCache('monsters', name, result);
930	        return result;
931	    }
932	
933	    /**
934	     * Batch enrichment with progress callback.
935	     * Respectfully rate-limited — each API hit spaced by RATE_LIMIT_MS.
936	     */
937	    public async batchEnrich(
938	        names: string[],
939	        type: 'item' | 'monster',
940	        onProgress?: (current: number, total: number, name: string) => void
941	    ): Promise<Map<string, WikiPageData>> {
942	        const results = new Map<string, WikiPageData>();
943	
944	        logger.info({ count: names.length, type }, 'Beginning batch wiki enrichment...');
945	
946	        for (let i = 0; i < names.length; i++) {
947	            const name = names[i];
948	            onProgress?.(i + 1, names.length, name);
949	
950	            try {
951	                const data = type === 'item'
952	                    ? await this.enrichItem(name)
953	                    : await this.enrichMonster(name);
954	                results.set(name, data);
955	            } catch (err) {
956	                logger.warn({ name, err }, 'Batch enrichment failed for entry.');
957	            }
958	        }
959	
960	        logger.info({ completed: results.size, total: names.length }, 'Batch enrichment complete.');
961	        return results;
962	    }
963	
964	    /**
965	     * Unified entry point for entity resolution.
966	     * Uses QueryClassifier to route requests between Structural (Cache) and Semantic (Wiki) paths.
967	     */
968	    public async enrichEntity(query: string): Promise<any> {
969	        const classified = QueryClassifier.classify(query);
970	        logger.info({ query, type: classified.type }, 'Classifying entity query...');
971	
972	        // 1. Route Structural Queries exclusively to CacheForensicsLimb
973	        if (classified.type.startsWith('structural_')) {
974	            const forensics = CacheForensicsLimb.getInstance();
975	            const id = classified.extractedIds[0];
976	
977	            if (classified.type === 'structural_enum') {
978	                return { type: 'enum', data: await forensics.getEnumDetails(id), tag: '[CACHE_VERIFIED]' };
979	            }
980	            if (classified.type === 'structural_id') {
981	                const item = await forensics.getItemDetails(id);
982	                const npc = await forensics.getNpcDetails(id);
983	                return { type: 'id_resolution', item, npc, tag: '[CACHE_VERIFIED]' };
984	            }
985	            return { type: 'structural', data: `Structural query ${classified.type} handled by CacheForensicsLimb`, tag: '[CACHE_EXCLUSIVE]' };
986	        }
987	
988	        // 2. Route Spatial Queries
989	        if (classified.type.startsWith('spatial_')) {
990	            return { type: 'spatial', query: classified.raw, tag: '[SPATIAL_SENSITIVE]' };
991	        }
992	
993	        // 3. Route Semantic/Hybrid Queries to Wiki + APIs
994	        const name = classified.extractedNames[0] || query;
995	
996	        // Try monster first, then item, then generic
997	        const monster = await this.enrichMonster(name);
998	        if (monster.monsterMeta) return { ...monster, tag: '[VERIFIED]' };
999	
1000	        const item = await this.enrichItem(name);
1001	        if (item.itemMeta) return { ...item, tag: '[VERIFIED]' };
1002	
1003	        return { ...await this.enrichGeneric(name), tag: '[WIKI_ONLY]' };
1004	    }
1005	
1006	    /**
1007	     * Tracks game updates for pedagogy freshness.
1008	     * Parses the Wiki Updates page to flag entities as [POST-UPDATE].
1009	     */
1010	    public async fetchLatestUpdates(): Promise<WikiUpdateMeta[]> {
1011	        logger.info('Fetching latest game updates for temporal grounding...');
1012	        const wikitext = await this.getWikitextForName('Updates');
1013	        if (!wikitext) return [];
1014	
1015	        const updates: WikiUpdateMeta[] = [];
1016	        // This is a simplified parser for the Updates page structure
1017	        const updateBlocks = wikitext.split('==');
1018	
1019	        for (const block of updateBlocks) {
1020	            const dateMatch = block.match(/(\d{1,2}\s\w+ \d{4})/);
1021	            if (!dateMatch) continue;
1022	
1023	            const date = dateMatch[1];
1024	            const titleMatch = block.match(/==\s*([^|]+?)\s*\|/);
1025	            const title = titleMatch ? titleMatch[1].trim() : 'Unknown Update';
1026	
1027	            updates.push({
1028	                title,
1029	                date,
1030	                category: 'General',
1031	                url: `https://runescape.wiki/w/Updates#${encodeURIComponent(title)}`,
1032	                isHotfix: block.toLowerCase().includes('hotfix'),
1033	                isColdfix: false,
1034	                affectedEntities: [] // Would require further parsing of the block text for IDs
1035	            });
1036	        }
1037	
1038	        return updates;
1039	    }
1040	
1041	    // ── Integration Helper ─────────────────────────────────
1042	
1043	    /**
