1045	     * Use this to fill gaps in item_definitions_enriched.json.
1046	     */
1047	    public toItemBookPatch(bonuses: WikiEquipmentBonuses): Record<string, any> {
1048	        const patch: Record<string, any> = {};
1049	
1050	        if (bonuses.tier > 0) {
1051	            const cls = bonuses.class.toLowerCase();
1052	            if (cls === 'melee' || bonuses.style === 'slash' || bonuses.style === 'stab' || bonuses.style === 'crush') {
1053	                patch.req_attack = bonuses.tier;
1054	            } else if (cls === 'ranged') {
1055	                patch.req_ranged = bonuses.tier;
1056	            } else if (cls === 'magic') {
1057	                patch.req_magic = bonuses.tier;
1058	            } else if (cls === 'necromancy') {
1059	                patch.req_necromancy = bonuses.tier;
1060	            }
1061	            patch.tier = bonuses.tier;
1062	        }
1063	
1064	        if (bonuses.damage > 0) patch.damage = bonuses.damage;
1065	        if (bonuses.accuracy > 0) patch.accuracy = bonuses.accuracy;
1066	        if (bonuses.armour > 0) patch.armour = bonuses.armour;
1067	        if (bonuses.lifeBonus > 0) patch.lifeBonus = bonuses.lifeBonus;
1068	        if (bonuses.prayerBonus > 0) patch.prayerBonus = bonuses.prayerBonus;
1069	        patch.slot = bonuses.slot;
1070	        patch.style = bonuses.style;
1071	        patch.attackSpeed = bonuses.attackSpeed;
1072	
1073	        return patch;
1074	    }
1075	
1076	    // ── Utilities ──────────────────────────────────────────
1077	
