1	/**
2	 * WikiEquipmentEnricher.ts
3	 *
4	 * Structured parser for RS Wiki Infobox templates and drop tables.
5	 * Extracts equipment bonuses, item metadata, monster stats, and complete
6	 * drop tables (including sub-table resolution) with respectful rate limiting.
7	 *
8	 * Sovereign Substrate: Semantic Enrichment Layer
9	 * Cache Authority: D:\sovereign\atlas\wiki\cache\
10	 *
11	 * Template Coverage:
12	 *   - {{Infobox Bonuses}}  → Equipment combat stats
13	 *   - {{Infobox Item}}     → Item metadata
14	 *   - {{Infobox Monster}}  → Monster/NPC stats
15	 *   - {{DropsLine}}        → Individual drop entries
16	 *   - {{Rare drop table}}, {{Gem drop table}}, etc. → Sub-table resolution
17	 */
18	
19	import { createLogger } from './logger.js';
20	import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'fs';
21	import { join } from 'path';
22	import { QueryClassifier, QueryType } from './QueryClassifier.js';
23	import { CacheForensicsLimb } from '../limbs/spatial/CacheForensicsLimb.js';
24	import { GeApi, GePrice } from './GeApi.js';
25	import { BestiaryApi, BestiaryBeastData } from './BestiaryApi.js';
26	
27	const logger = createLogger('WikiEquipmentEnricher');
28	
29	// ═══════════════════════════════════════════════════════
30	// Interfaces
31	// ═══════════════════════════════════════════════════════
32	
33	export interface WikiEquipmentBonuses {
34	    tier: number | null;
35	    slot: string | null;          // mainhand, off-hand, 2h, head, body, legs, feet, hands, back, neck, ring, ammo, pocket, shield
36	    class: string | null;         // melee, ranged, magic, necromancy, all, hybrid
37	    style: string | null;         // slash, stab, crush, none
38	    damage: number | null;
39	    accuracy: number | null;
40	    armour: number | null;
41	    lifeBonus: number | null;
42	    prayerBonus: number | null;
43	    attackSpeed: string | null;   // fastest, fast, average, slow, slowest
44	}
45	
46	export interface WikiMonsterMeta {
47	    name: string;
48	    combatLevel: number | null;
49	    lifePoints: number | null;
50	    maxHit: number | null;
51	    weakness: string | null;
52	    slayerLevel: number | null;
53	    slayerCategory: string | null;
54	    aggressive: boolean | null;
55	    poisonous: boolean | null;
56	    attackStyle: string | null;
57	    members: boolean | null;
58	    experience: number | null;
59	
60	    // March 2026 Combat Affinities
61	    defence: number | null;
62	    armour: number | null;
63	    affinityMelee: number | null;
64	    affinityRanged: number | null;
65	    affinityMagic: number | null;
66	    affinityNecromancy: number | null;
67	}
68	
69	export interface WikiDropEntry {
70	    itemName: string;
71	    quantity: string;       // "1", "1-3", "1 (noted)", etc.
72	    rarity: string;         // "Always", "Common", "Uncommon", "Rare", "Very rare", "1/128"
73	    isMembers: boolean;
74	    notes: string;
75	    /** Grand Exchange value in coins. 0 = not tradeable or unknown. Used by LootBeamRegistry. */
76	    geValue: number;
77	}
78	
79	export interface WikiDropTable {
80	    section: string;        // "Main", "Charms", "Tertiary", sub-table name
81	    entries: WikiDropEntry[];
82	}
83	
84	export interface WikiPageData {
85	    title: string;
86	    fetchedAt: number;
87	    bonuses: WikiEquipmentBonuses | null;
88	    itemMeta: WikiItemMeta | null;
89	    monsterMeta: WikiMonsterMeta | null;
90	    dropTables: WikiDropTable[];
91	    rawVariables: Record<string, string>;
92	    pageType?: 'npc' | 'item' | 'equipment' | 'place' | 'mechanic' | 'lore';
93	    extract?: string;
94	    categoryMembers?: string[];
95	}
96	
97	export interface WikiUpdateMeta {
98	    title: string;
99	    date: string;
100	    category: string;
101	    url: string;
102	    isHotfix: boolean;
103	    isColdfix: boolean;
104	    affectedEntities: number[];
105	}
106	
107	// ═══════════════════════════════════════════════════════
108	// Generic Enrichment Types
109	// ═══════════════════════════════════════════════════════
110	
111	export interface WikiGenericMeta {
112	    title: string;
113	    pageType: 'npc' | 'item' | 'equipment' | 'place' | 'mechanic' | 'lore';
114	    extract: string;
115	    infoboxVars: Record<string, string>;
116	    categoryMembers?: string[];
117	    fetchedAt: number;
118	}
119	
120	export class WikiEquipmentEnricher {
121	    private static instance: WikiEquipmentEnricher;
122	
123	    private readonly API_BASE = 'https://runescape.wiki/api.php';
124	    private readonly USER_AGENT = 'POG2-Sovereign/1.0 (Sovereign Research Node; admin@pog2.internal; respectful-soft-parse; +https://github.com/Kbro1989/POG2)';
125	    private readonly RATE_LIMIT_MS = 1500;
126	    private readonly CACHE_DIR: string;
127	    private readonly CACHE_TTL_MS = 7 * 24 * 60 * 60 * 1000; // 7 days
128	
129	    private lastRequestTime = 0;
130	    private requestCount = 0;
131	
132	    private constructor() {
133	        this.CACHE_DIR = join('D:', 'sovereign', 'atlas', 'wiki', 'cache');
134	        this.ensureCacheDir();
135	    }
136	
137	    public static getInstance(): WikiEquipmentEnricher {
138	        if (!this.instance) {
139	            this.instance = new WikiEquipmentEnricher();
140	        }
141	        return this.instance;
142	    }
143	
144	    // ── Cache Layer ────────────────────────────────────────
145	
146	    private ensureCacheDir(): void {
147	        const dirs = [
148	            this.CACHE_DIR,
149	            join(this.CACHE_DIR, 'items'),
150	            join(this.CACHE_DIR, 'monsters'),
151	            join(this.CACHE_DIR, 'templates'),
152	            join(this.CACHE_DIR, 'wikitext'),
153	            join(this.CACHE_DIR, 'generic')
154	        ];
155	        for (const dir of dirs) {
156	            if (!existsSync(dir)) {
157	                mkdirSync(dir, { recursive: true });
158	            }
159	        }
160	    }
161	
162	    private sanitizeFilename(name: string): string {
163	        return name.replace(/[<>:"/\\|?*]/g, '_').replace(/\s+/g, '_').toLowerCase();
164	    }
165	
166	    private readCache(subdir: string, key: string): any | null {
167	        const filePath = join(this.CACHE_DIR, subdir, `${this.sanitizeFilename(key)}.json`);
168	        if (!existsSync(filePath)) return null;
169	
170	        try {
171	            const raw = readFileSync(filePath, 'utf8');
172	            const cached = JSON.parse(raw);
173	
174	            // TTL check
175	            if (cached._cachedAt && (Date.now() - cached._cachedAt) > this.CACHE_TTL_MS) {
176	                logger.debug({ key }, 'Cache expired, will re-fetch.');
177	                return null;
178	            }
179	
180	            return cached;
181	        } catch {
182	            return null;
183	        }
184	    }
185	
186	    private writeCache(subdir: string, key: string, data: any): void {
187	        const filePath = join(this.CACHE_DIR, subdir, `${this.sanitizeFilename(key)}.json`);
188	        try {
189	            writeFileSync(filePath, JSON.stringify({ ...data, _cachedAt: Date.now() }, null, 2), 'utf8');
190	        } catch (err) {
191	            logger.warn({ key, err }, 'Failed to write cache.');
192	        }
193	    }
194	
195	    // ── Rate Limiter ───────────────────────────────────────
196	
197	    private async throttle(): Promise<void> {
198	        const now = Date.now();
199	        const elapsed = now - this.lastRequestTime;
200	        if (elapsed < this.RATE_LIMIT_MS) {
201	            const delay = this.RATE_LIMIT_MS - elapsed;
202	            await new Promise(resolve => setTimeout(resolve, delay));
203	        }
204	        this.lastRequestTime = Date.now();
205	        this.requestCount++;
206	    }
207	
208	    // ── API Layer ──────────────────────────────────────────
209	
210	    /**
211	     * Fetch raw wikitext for a page. Checks disk cache first.
212	     */
213	    private async fetchWikitext(pageTitle: string): Promise<string | null> {
214	        const cached = this.readCache('wikitext', pageTitle);
215	        if (cached?.wikitext) {
216	            logger.debug({ title: pageTitle }, 'Wikitext served from cache.');
217	            return cached.wikitext;
218	        }
219	
220	        await this.throttle();
221	
222	        const params = new URLSearchParams({
223	            action: 'parse',
224	            format: 'json',
225	            page: pageTitle,
226	            prop: 'wikitext',
227	            origin: '*'
228	        });
229	
230	        try {
231	            const response = await fetch(`${this.API_BASE}?${params.toString()}`, {
232	                headers: {
233	                    'User-Agent': this.USER_AGENT,
234	                    'Accept': 'application/json'
235	                },
236	                signal: AbortSignal.timeout(10000)
237	            });
238	
239	            if (!response.ok) {
240	                if (response.status === 429) {
241	                    const retryAfter = response.headers.get('Retry-After');
242	                    if (retryAfter) {
243	                        ApiThrottle.getInstance().reportRetryAfter('wiki', parseInt(retryAfter, 10));
244	                    }
245	                }
246	                logger.warn({ title: pageTitle, status: response.status }, 'Wiki API non-OK response.');
247	                return null;
248	            }
249	
250	            const data = await response.json() as any;
251	            const wikitext = data.parse?.wikitext?.['*'] || null;
252	
253	            if (wikitext) {
254	                this.writeCache('wikitext', pageTitle, { wikitext });
255	                logger.info({ title: pageTitle, length: wikitext.length, request: this.requestCount }, 'Wikitext fetched.');
256	            }
257	
258	            return wikitext;
259	        } catch (err) {
260	            logger.error({ title: pageTitle, err }, 'Failed to fetch wikitext.');
261	            return null;
262	        }
263	    }
264	
265	    /**
266	     * Search for the canonical page title matching a query.
267	     */
268	    private async searchPage(query: string): Promise<string | null> {
269	        await this.throttle();
270	
271	        const params = new URLSearchParams({
