305	    /**
306	     * Resolves a name to wikitext. Tries direct fetch, follows redirects, falls back to search.
307	     */
308	    private async getWikitextForName(name: string): Promise<string | null> {
309	        const visited = new Set<string>();
310	        let currentName = name;
311	
312	        while (true) {
313	            if (visited.has(currentName.toLowerCase())) {
314	                logger.warn({ name, visited: [...visited] }, 'Redirect loop detected');
315	                return null;
316	            }
317	            visited.add(currentName.toLowerCase());
318	
319	            let wikitext = await this.fetchWikitext(currentName);
320	
321	            if (wikitext && wikitext.trim().startsWith('#REDIRECT')) {
322	                const redirectMatch = wikitext.match(/\[\[([^\]]+)\]\]/);
323	                if (redirectMatch) {
324	                    const redirectTarget = redirectMatch[1].trim();
325	                    logger.info({ from: currentName, to: redirectTarget }, 'Following wiki redirect...');
326	                    currentName = redirectTarget;
327	                    continue;
328	                }
329	            }
330	
331	            return wikitext;
332	        }
333	    }
