337	    /**
338	     * Extract a single template's parameters from wikitext.
339	     * Handles nested templates via bracket-depth tracking.
340	     */
341	    private extractTemplate(wikitext: string, templateName: string): Record<string, string> | null {
342	        const lowerText = wikitext.toLowerCase();
343	        const lowerName = templateName.toLowerCase();
344	
345	        let searchIdx = 0;
346	        let startIdx = -1;
347	
348	        while (searchIdx < lowerText.length) {
349	            const bracePos = lowerText.indexOf('{{', searchIdx);
350	            if (bracePos === -1) break;
351	
352	            let nameStart = bracePos + 2;
353	            while (nameStart < lowerText.length && (lowerText[nameStart] === ' ' || lowerText[nameStart] === '\n')) nameStart++;
354	
355	            if (lowerText.substring(nameStart, nameStart + lowerName.length) === lowerName) {
356	                const afterName = lowerText[nameStart + lowerName.length];
357	                if (afterName === '|' || afterName === '}' || afterName === ' ' || afterName === '\n' || afterName === '\r' || afterName === undefined) {
358	                    startIdx = bracePos;
359	                    break;
360	                }
361	            }
362	            searchIdx = bracePos + 2;
363	        }
364	
365	        if (startIdx === -1) return null;
366	
367	        // Find matching closing }} using bracket depth
368	        let depth = 0;
369	        let endIdx = startIdx;
370	        for (let i = startIdx; i < wikitext.length - 1; i++) {
371	            if (wikitext[i] === '{' && wikitext[i + 1] === '{') {
372	                depth++;
373	                i++;
374	            } else if (wikitext[i] === '}' && wikitext[i + 1] === '}') {
375	                depth--;
376	                i++;
377	                if (depth === 0) {
378	                    endIdx = i + 1;
379	                    break;
380	                }
381	            }
382	        }
383	
384	        if (depth !== 0) return null;
385	
386	        const fullContent = wikitext.substring(startIdx + 2, endIdx - 2);
387	        const pipeIdx = fullContent.indexOf('|');
388	        if (pipeIdx === -1) return {};
389	
390	        return this.parseTemplateParams(fullContent.substring(pipeIdx + 1));
391	    }
392	
393	    /**
394	     * Extract ALL instances of a template from wikitext.
395	     * Critical for DropsLine parsing where each drop is a separate template call.
396	     */
397	    private extractAllTemplateInstances(wikitext: string, templateName: string): Record<string, string>[] {
398	        const results: Record<string, string>[] = [];
399	        const lowerText = wikitext.toLowerCase();
400	        const lowerName = templateName.toLowerCase();
401	        let searchIdx = 0;
402	
403	        while (searchIdx < lowerText.length) {
404	            const bracePos = lowerText.indexOf('{{', searchIdx);
405	            if (bracePos === -1) break;
406	
407	            let nameStart = bracePos + 2;
408	            while (nameStart < lowerText.length && (lowerText[nameStart] === ' ' || lowerText[nameStart] === '\n')) nameStart++;
409	
410	            if (lowerText.substring(nameStart, nameStart + lowerName.length) === lowerName) {
411	                const afterName = lowerText[nameStart + lowerName.length];
412	                if (afterName === '|' || afterName === '}' || afterName === ' ' || afterName === '\n') {
413	                    // Find closing braces
414	                    let depth = 0;
415	                    let endIdx = bracePos;
416	                    for (let i = bracePos; i < wikitext.length - 1; i++) {
417	                        if (wikitext[i] === '{' && wikitext[i + 1] === '{') { depth++; i++; }
418	                        else if (wikitext[i] === '}' && wikitext[i + 1] === '}') {
419	                            depth--; i++;
420	                            if (depth === 0) { endIdx = i + 1; break; }
421	                        }
422	                    }
423	
424	                    const fullContent = wikitext.substring(bracePos + 2, endIdx - 2);
425	                    const pipeIdx = fullContent.indexOf('|');
426	                    if (pipeIdx !== -1) {
427	                        results.push(this.parseTemplateParams(fullContent.substring(pipeIdx + 1)));
428	                    }
429	
430	                    searchIdx = endIdx;
431	                    continue;
432	                }
433	            }
434	            searchIdx = bracePos + 2;
435	        }
436	
437	        return results;
438	    }
