440	    /**
441	     * Parse pipe-separated template parameters, respecting nested template depth.
442	     * Handles {{nested|templates}} and [[wiki|links]] inside parameter values.
443	     */
444	    private parseTemplateParams(text: string): Record<string, string> {
445	        const params: Record<string, string> = {};
446	        let depth = 0;
447	        let currentParam = '';
448	        let positionalIdx = 1;
449	
450	        for (let i = 0; i < text.length; i++) {
451	            const ch = text[i];
452	            const next = text[i + 1];
453	
454	            if (ch === '{' && next === '{') { depth++; currentParam += '{{'; i++; }
455	            else if (ch === '}' && next === '}') { depth--; currentParam += '}}'; i++; }
456	            else if (ch === '[' && next === '[') { depth++; currentParam += '[['; i++; }
457	            else if (ch === ']' && next === ']') { depth--; currentParam += ']]'; i++; }
458	            else if (ch === '|' && depth === 0) {
459	                this.assignParam(params, currentParam, positionalIdx);
460	                positionalIdx++;
461	                currentParam = '';
462	            } else {
463	                currentParam += ch;
464	            }
465	        }
466	
467	        // Last parameter
468	        if (currentParam.trim()) {
469	            this.assignParam(params, currentParam, positionalIdx);
470	        }
471	
472	        return params;
473	    }
474	
475	    private assignParam(params: Record<string, string>, raw: string, positionalIdx: number): void {
476	        const eqIdx = raw.indexOf('=');
477	        if (eqIdx > 0 && !raw.substring(0, eqIdx).includes('{{')) {
478	            const key = raw.substring(0, eqIdx).trim().toLowerCase();
479	            const value = this.cleanWikiMarkup(raw.substring(eqIdx + 1).trim());
480	            if (key) params[key] = value;
481	        } else {
482	            params[`_${positionalIdx}`] = this.cleanWikiMarkup(raw.trim());
483	        }
484	    }
485	
486	    /**
487	     * Strip wiki markup from a value (links, formatting, refs).
488	     */
489	    private cleanWikiMarkup(text: string): string {
490	        return text
491	            .replace(/\[\[(?:[^\]|]*\|)?([^\]]*)\]\]/g, '$1')  // [[Link|Text]] -> Text
492	            .replace(/'''?/g, '')                                // Bold/italic
493	            .replace(/<ref[^>]*>.*?<\/ref>/gs, '')               // References
494	            .replace(/<ref[^/]*\/>/g, '')                        // Self-closing refs
495	            .replace(/<br\s*\/?>/gi, ' ')                        // Line breaks
496	            .replace(/<!--.*?-->/gs, '')                         // HTML comments
497	            .replace(/&nbsp;/g, ' ')                             // Non-breaking spaces
498	            .trim();
499	    }
