677	    /**
678	     * Fetch and parse a sub-drop-table template page.
679	     * These live at Template:{name} on the wiki.
680	     */
681	    private async resolveSubTable(templateName: string): Promise<WikiDropEntry[]> {
682	        // Check cache
683	        const cached = this.readCache('templates', templateName);
684	        if (cached?.entries) {
685	            logger.debug({ templateName }, 'Sub-table served from cache.');
686	            return cached.entries;
687	        }
688	
689	        // Fetch the template page
690	        const wikitext = await this.fetchWikitext(`Template:${templateName}`);
691	        if (!wikitext) return [];
692	
693	        const dropLines = this.extractAllTemplateInstances(wikitext, 'DropsLine');
694	        const entries: WikiDropEntry[] = dropLines.map(dl => ({
695	            itemName: dl['name'] || dl['_1'] || 'Unknown',
696	            quantity: dl['quantity'] || dl['_2'] || '1',
697	            rarity: dl['rarity'] || dl['_3'] || 'Unknown',
698	            isMembers: this.safeBool(dl['members']),
699	            notes: `[${templateName}] ${dl['raritynotes'] || ''}`.trim(),
700	            // Sub-tables (RDT, Gem table) typically have no direct GE price in the template.
701	            // geValue defaults to 0; LootBeamRegistry will use the rarity label (e.g. "Rare drop table") instead.
702	            geValue: this.safeInt(dl['ge'] || dl['value'] || '0')
703	        }));
704	
705	        // Cache the resolved sub-table
706	        this.writeCache('templates', templateName, { entries });
707	        logger.info({ templateName, count: entries.length }, 'Sub-table resolved and cached.');
708	
709	        return entries;
710	    }
