714	    private detectPageType(wikitext: string): 'npc' | 'item' | 'equipment' | 'place' | 'mechanic' | 'lore' {
715	        const lower = wikitext.toLowerCase();
716	        if (lower.includes('{{infobox monster')) return 'npc';
717	        if (lower.includes('{{infobox item')) return 'item';
718	        if (lower.includes('{{infobox bonuses')) return 'equipment';
719	        if (lower.includes("{{infobox location") || lower.includes("{{infobox area")) return 'place';
720	        if (lower.includes("{{infobox mechanic") || lower.includes("{{infobox gameplay")) return 'mechanic';
721	        return 'lore';
722	    }
