858	        };
859	
860	        this.writeCache('items', name, result);
861	        return result;
862	    }
863	
864	    /**
865	     * Full enrichment pipeline for a monster/NPC.
866	     * Returns stats, drop tables (with sub-tables), and all raw infobox variables.
867	     */
868	    public async enrichMonster(name: string): Promise<WikiPageData> {
869	        const cached = this.readCache('monsters', name);
870	        if (cached && cached.title) {
871	            logger.debug({ name }, 'Monster enrichment served from cache.');
872	            return cached;
873	        }
874	
875	        const monsterMeta = await this.parseMonsterMeta(name);
876	        const dropTables = await this.parseDropTables(name);
877	
878	        // 🧬 Integration: Canonical Bestiary Enrichment
879	        if (monsterMeta) {
880	            const beastId = await BestiaryApi.resolveId(name);
881	            if (beastId) {
882	                const beastData = await BestiaryApi.getBeastData(beastId);
883	                if (beastData) {
884	                    monsterMeta.combatLevel = beastData.level;
885	                    monsterMeta.lifePoints = beastData.lifepoints;
886	                    monsterMeta.weakness = beastData.weakness;
887	                    monsterMeta.slayerLevel = beastData.slayerlevel;
888	                    monsterMeta.slayerCategory = beastData.slayercat;
889	                    monsterMeta.aggressive = beastData.aggressive;
890	                    monsterMeta.poisonous = beastData.poisonous;
891	                    monsterMeta.members = beastData.members;
892	                    logger.debug({ name, id: beastId }, 'Canonical Bestiary data applied to monster meta.');
893	                }
894	            }
895	        }
896	
897	        const wikitext = await this.getWikitextForName(name);
898	        const rawVariables = wikitext
899	            ? (this.extractTemplate(wikitext, 'Infobox Monster') || {})
900	            : {};
901	
902	        const result: WikiPageData = {
903	            title: name,
904	            fetchedAt: Date.now(),
905	            bonuses: null,
906	            itemMeta: null,
907	            monsterMeta,
908	            dropTables,
909	            rawVariables
910	        };
911	
912	        this.writeCache('monsters', name, result);
913	        return result;
914	    }
915	
916	    /**
917	     * Batch enrichment with progress callback.
918	     * Respectfully rate-limited — each API hit spaced by RATE_LIMIT_MS.
919	     */
920	    public async batchEnrich(
921	        names: string[],
922	        type: 'item' | 'monster',
923	        onProgress?: (current: number, total: number, name: string) => void
924	    ): Promise<Map<string, WikiPageData>> {
925	        const results = new Map<string, WikiPageData>();
926	
927	        logger.info({ count: names.length, type }, 'Beginning batch wiki enrichment...');
928	
929	        for (let i = 0; i < names.length; i++) {
930	            const name = names[i];
931	            onProgress?.(i + 1, names.length, name);
932	
933	            try {
934	                const data = type === 'item'
935	                    ? await this.enrichItem(name)
936	                    : await this.enrichMonster(name);
937	                results.set(name, data);
938	            } catch (err) {
939	                logger.warn({ name, err }, 'Batch enrichment failed for entry.');
940	            }
941	        }
942	
943	        logger.info({ completed: results.size, total: names.length }, 'Batch enrichment complete.');
944	        return results;
945	    }
946	
947	    /**
948	     * Unified entry point for entity resolution.
949	     * Uses QueryClassifier to route requests between Structural (Cache) and Semantic (Wiki) paths.
950	     */
951	    public async enrichEntity(query: string): Promise<any> {
952	        const classified = QueryClassifier.classify(query);
953	        logger.info({ query, type: classified.type }, 'Classifying entity query...');
954	
955	        // 1. Route Structural Queries exclusively to CacheForensicsLimb
956	        if (classified.type.startsWith('structural_')) {
957	            const forensics = CacheForensicsLimb.getInstance();
958	            const id = classified.extractedIds[0];
959	
960	            if (classified.type === 'structural_enum') {
961	                return { type: 'enum', data: await forensics.getEnumDetails(id), tag: '[CACHE_VERIFIED]' };
962	            }
963	            if (classified.type === 'structural_id') {
964	                const item = await forensics.getItemDetails(id);
965	                const npc = await forensics.getNpcDetails(id);
966	                return { type: 'id_resolution', item, npc, tag: '[CACHE_VERIFIED]' };
967	            }
968	            return { type: 'structural', data: `Structural query ${classified.type} handled by CacheForensicsLimb`, tag: '[CACHE_EXCLUSIVE]' };
969	        }
970	
971	        // 2. Route Spatial Queries
972	        if (classified.type.startsWith('spatial_')) {
973	            return { type: 'spatial', query: classified.raw, tag: '[SPATIAL_SENSITIVE]' };
974	        }
975	
976	        // 3. Route Semantic/Hybrid Queries to Wiki + APIs
977	        const name = classified.extractedNames[0] || query;
978	
979	        // Try monster first, then item, then generic
980	        const monster = await this.enrichMonster(name);
981	        if (monster.monsterMeta) return { ...monster, tag: '[VERIFIED]' };
982	
983	        const item = await this.enrichItem(name);
984	        if (item.itemMeta) return { ...item, tag: '[VERIFIED]' };
985	
986	        return { ...await this.enrichGeneric(name), tag: '[WIKI_ONLY]' };
987	    }
988	
989	    /**
990	     * Tracks game updates for pedagogy freshness.
991	     * Parses the Wiki Updates page to flag entities as [POST-UPDATE].
992	     */
993	    public async fetchLatestUpdates(): Promise<WikiUpdateMeta[]> {
994	        logger.info('Fetching latest game updates for temporal grounding...');
995	        const wikitext = await this.getWikitextForName('Updates');
996	        if (!wikitext) return [];
997	
998	        const updates: WikiUpdateMeta[] = [];
999	        // This is a simplified parser for the Updates page structure
1000	        const updateBlocks = wikitext.split('==');
1001	
1002	        for (const block of updateBlocks) {
1003	            const dateMatch = block.match(/(\d{1,2}\s\w+ \d{4})/);
1004	            if (!dateMatch) continue;
1005	
1006	            const date = dateMatch[1];
1007	            const titleMatch = block.match(/==\s*([^|]+?)\s*\|/);
1008	            const title = titleMatch ? titleMatch[1].trim() : 'Unknown Update';
1009	
1010	            updates.push({
1011	                title,
1012	                date,
1013	                category: 'General',
1014	                url: `https://runescape.wiki/w/Updates#${encodeURIComponent(title)}`,
1015	                isHotfix: block.toLowerCase().includes('hotfix'),
1016	                isColdfix: false,
1017	                affectedEntities: [] // Would require further parsing of the block text for IDs
1018	            });
1019	        }
1020	
1021	        return updates;
1022	    }
1023	
1024	    // ── Integration Helper ─────────────────────────────────
1025	
1026	    /**
1027	     * Converts wiki bonuses into a patch compatible with ItemBook's semanticStats.
1028	     * Use this to fill gaps in item_definitions_enriched.json.
1029	     */
1030	    public toItemBookPatch(bonuses: WikiEquipmentBonuses): Record<string, any> {
1031	        const patch: Record<string, any> = {};
1032	
1033	        if (bonuses.tier > 0) {
1034	            const cls = bonuses.class.toLowerCase();
1035	            if (cls === 'melee' || bonuses.style === 'slash' || bonuses.style === 'stab' || bonuses.style === 'crush') {
1036	                patch.req_attack = bonuses.tier;
1037	            } else if (cls === 'ranged') {
1038	                patch.req_ranged = bonuses.tier;
1039	            } else if (cls === 'magic') {
1040	                patch.req_magic = bonuses.tier;
1041	            } else if (cls === 'necromancy') {
1042	                patch.req_necromancy = bonuses.tier;
1043	            }
1044	            patch.tier = bonuses.tier;
1045	        }
1046	
1047	        if (bonuses.damage > 0) patch.damage = bonuses.damage;
1048	        if (bonuses.accuracy > 0) patch.accuracy = bonuses.accuracy;
1049	        if (bonuses.armour > 0) patch.armour = bonuses.armour;
1050	        if (bonuses.lifeBonus > 0) patch.lifeBonus = bonuses.lifeBonus;
1051	        if (bonuses.prayerBonus > 0) patch.prayerBonus = bonuses.prayerBonus;
1052	        patch.slot = bonuses.slot;
1053	        patch.style = bonuses.style;
1054	        patch.attackSpeed = bonuses.attackSpeed;
1055	
1056	        return patch;
1057	    }
1058	
1059	    // ── Utilities ──────────────────────────────────────────
1060	
1061	    private safeInt(value: string | undefined): number | null {
1062	        if (value === undefined) return null;
1063	        const cleaned = value.replace(/,/g, '').replace(/[^0-9.-]/g, '');
1064	        if (cleaned === '') return null;
